messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: bfd/coff-go32.c
Line: 139
Function: _bfd_go32_swap_scnhdr_out
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: Uses strcmp on internal_scnhdr->s_name, which is also an 8-byte fixed field and may not be NUL-terminated (it is filled via memcpy from the external header). When EXEC_P is set, strcmp can read beyond the 8-byte array into adjacent memory if the section name consists of 8 non-NUL bytes. Triggerable when writing an executable with such a section name.

Source context:
```c
       99:   scnhdr_int->s_size = GET_SCNHDR_SIZE (abfd, scnhdr_ext->s_size);
      100: 
      101:   scnhdr_int->s_scnptr = GET_SCNHDR_SCNPTR (abfd, scnhdr_ext->s_scnptr);
      102:   scnhdr_int->s_relptr = GET_SCNHDR_RELPTR (abfd, scnhdr_ext->s_relptr);
      103:   scnhdr_int->s_lnnoptr = GET_SCNHDR_LNNOPTR (abfd, scnhdr_ext->s_lnnoptr);
      104:   scnhdr_int->s_flags = GET_SCNHDR_FLAGS (abfd, scnhdr_ext->s_flags);
      105:   scnhdr_int->s_nreloc = GET_SCNHDR_NRELOC (abfd, scnhdr_ext->s_nreloc);
      106:   scnhdr_int->s_nlnno = GET_SCNHDR_NLNNO (abfd, scnhdr_ext->s_nlnno);
      107: 
      108:   /* DJGPP follows the same strategy as PE COFF.
      109:      Iff the file is an executable then the higher 16 bits
      110:      of the line number have been stored in the relocation
      111:      counter field.  */
      112:   if (abfd->flags & EXEC_P && (strcmp (scnhdr_ext->s_name, ".text") == 0))
      113:     {
      114:       scnhdr_int->s_nlnno
      115: 	= (GET_SCNHDR_NRELOC (abfd, scnhdr_ext->s_nreloc) << 16)
      116: 	  + GET_SCNHDR_NLNNO (abfd, scnhdr_ext->s_nlnno);
      117:       scnhdr_int->s_nreloc = 0;
      118:     }
      119: }
      120: 
      121: unsigned int
      122: _bfd_go32_swap_scnhdr_out (bfd *abfd, void *in, void *out,
      123: 			   const asection *section ATTRIBUTE_UNUSED)
      124: {
      125:   struct internal_scnhdr *scnhdr_int = (struct internal_scnhdr *) in;
      126:   SCNHDR *scnhdr_ext = (SCNHDR *) out;
      127:   unsigned int ret = bfd_coff_scnhsz (abfd);
      128: 
      129:   memcpy (scnhdr_ext->s_name, scnhdr_int->s_name, sizeof (scnhdr_int->s_name));
      130: 
      131:   PUT_SCNHDR_VADDR (abfd, scnhdr_int->s_vaddr, scnhdr_ext->s_vaddr);
      132:   PUT_SCNHDR_PADDR (abfd, scnhdr_int->s_paddr, scnhdr_ext->s_paddr);
      133:   PUT_SCNHDR_SIZE (abfd, scnhdr_int->s_size, scnhdr_ext->s_size);
      134:   PUT_SCNHDR_SCNPTR (abfd, scnhdr_int->s_scnptr, scnhdr_ext->s_scnptr);
      135:   PUT_SCNHDR_RELPTR (abfd, scnhdr_int->s_relptr, scnhdr_ext->s_relptr);
      136:   PUT_SCNHDR_LNNOPTR (abfd, scnhdr_int->s_lnnoptr, scnhdr_ext->s_lnnoptr);
      137:   PUT_SCNHDR_FLAGS (abfd, scnhdr_int->s_flags, scnhdr_ext->s_flags);
      138: 
>>>   139:   if (abfd->flags & EXEC_P && (strcmp (scnhdr_int->s_name, ".text") == 0))
      140:     {
      141:       /* DJGPP follows the same strategy as PE COFF.
      142: 	 By inference from looking at MS output, the 32 bit field
      143: 	 which is the combination of the number_of_relocs and
      144: 	 number_of_linenos is used for the line number count in
      145: 	 executables.  A 16-bit field won't do for cc1.  The MS
      146: 	 document says that the number of relocs is zero for
      147: 	 executables, but the 17-th bit has been observed to be there.
      148: 	 Overflow is not an issue: a 4G-line program will overflow a
      149: 	 bunch of other fields long before this!  */
      150:       PUT_SCNHDR_NLNNO (abfd, (scnhdr_int->s_nlnno & 0xffff),
      151: 			scnhdr_ext->s_nlnno);
      152:       PUT_SCNHDR_NRELOC (abfd, (scnhdr_int->s_nlnno >> 16),
      153: 			 scnhdr_ext->s_nreloc);
      154:     }
      155:   else
      156:     {
      157:       /* DJGPP follows the same strategy as PE COFF.  */
      158:       if (scnhdr_int->s_nlnno <= MAX_SCNHDR_NLNNO)
      159: 	PUT_SCNHDR_NLNNO (abfd, scnhdr_int->s_nlnno, scnhdr_ext->s_nlnno);
      160:       else
      161: 	{
      162: 	  char buf[sizeof (scnhdr_int->s_name) + 1];
      163: 
      164: 	  memcpy (buf, scnhdr_int->s_name, sizeof (scnhdr_int->s_name));
      165: 	  buf[sizeof (scnhdr_int->s_name)] = '\0';
      166: 	  _bfd_error_handler
      167: 	    /* xgettext:c-format */
      168: 	    (_("%pB: warning: %s: line number overflow: 0x%lx > 0xffff"),
      169: 	     abfd, buf, scnhdr_int->s_nlnno);
      170: 	  bfd_set_error (bfd_error_file_truncated);
      171: 	  PUT_SCNHDR_NLNNO (abfd, 0xffff, scnhdr_ext->s_nlnno);
      172: 	  ret = 0;
      173: 	}
      174: 
      175:       /* Although we could encode 0xffff relocs here, we do not, to be
      176: 	 consistent with other parts of bfd.  Also it lets us warn, as
      177: 	 we should never see 0xffff here w/o having the overflow flag
      178: 	 set.  */
      179:       if (scnhdr_int->s_nreloc < MAX_SCNHDR_NRELOC)
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/binutils_upstream reproducer.c -L/tmp/binutils_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/binutils_upstream
